import React from 'react';

const InfoBar = () => {
  return (
    <div className="info-bar">
      <span>Releasetrain <span style={{ color: '#4da6ff' }}>v3.1.0</span></span>
      <span className="getComponentCount">Components: <span style={{ color: '#4da6ff' }}>Loading...</span></span>
      <span className="getVersionCount">Versions: <span style={{ color: '#4da6ff' }}>Loading...</span></span>
      <span className="getRedditCount">Reddit: <span style={{ color: '#4da6ff' }}>Loading...</span></span>
      <span className="currentPageVersions">Page Versions: <span style={{ color: '#4da6ff' }}>0</span></span>
      <span className="dateRangeLabel" style={{ color: '#888' }}></span>
      <a
        href="https://github.com/antrunner/releasetrain-client"
        target="_blank"
        rel="noreferrer"
        style={{ color: '#4da6ff', fontWeight: 'bold', textDecoration: 'none' }}
      >
        GitHub ↗
      </a>
    </div>
  );
};

export default InfoBar;
